-- Refer to https://wiki.hypr.land/configuring/core/config-options/

hl.config({
    general = {
        gaps_in = 5,
        gaps_out = 12,
        border_size = 3,

        col = {
            active_border = "rgb(36454F)",
            inactive_border = "rgba(3b2f2faa)",
        },

        resize_on_border = false,
        allow_tearing = false,
        layout = "dwindle",
    },

    decoration = {
        rounding = 15,
        rounding_power = 2,

        active_opacity = 0.73,
        inactive_opacity = 0.73,

        shadow = {
            enabled = true,
            range = 10,
            render_power = 4,
            color = "rgba(1a1a1aee)",
        },

        blur = {
            enabled = true,
            size = 10,
            passes = 4,
            vibrancy = 0.2,
        },
    },

    animations = {
        enabled = true,
    },
})


-- Default curves and animations, see https://wiki.hypr.land/configuring/core/animations/

-- Original custom animation curves

hl.curve("easeOutQuint", {
    type = "bezier",
    points = {{0.22, 1}, {0.36, 1.0099999}}
})

hl.curve("easeInOutCubic", {
    type = "bezier",
    points = {{0.65, 0.05}, {0.36, 1.0099999}}
})

hl.curve("linear", {
    type = "bezier",
    points = {{0, 0}, {1, 1.0099999}}
})

hl.curve("almostLinear", {
    type = "bezier",
    points = {{0.22, 1}, {0.36, 1.0099999}}
})

hl.curve("quick", {
    type = "bezier",
    points = {{0.11, 0}, {0.1, 1.0099999}}
})

hl.curve("smoothOut", {
    type = "bezier",
    points = {{0.36, 0}, {0.66, -0.25}}
})

hl.curve("smoothIn", {
    type = "bezier",
    points = {{0.25, 1}, {0.5, 1}}
})

hl.curve("fluent", {
    type = "bezier",
    points = {{0.46, 1}, {0.29, 0.99}}
})

hl.curve("butter", {
    type = "bezier",
    points = {{.5, 0.9}, {.1, 1.1}}
})

hl.curve("butterSoft", {
    type = "bezier",
    points = {{0.2, 1}, {0.3, 1}}
})

-- Original animation settings

hl.animation({leaf = "global", enabled = true, speed = 10, bezier = "default"})
hl.animation({leaf = "border", enabled = true, speed = 10, bezier = "easeOutQuint"})
hl.animation({leaf = "windows", enabled = true, speed = 10, bezier = "easeOutQuint", style = "popin 65%"})
hl.animation({leaf = "windowsIn", enabled = true, speed = 10, bezier = "easeOutQuint", style = "popin 65%"})
hl.animation({leaf = "windowsOut", enabled = true, speed = 10, bezier = "easeOutQuint", style = "popin 0%"})
hl.animation({leaf = "fadeIn", enabled = true, speed = 7, bezier = "easeOutQuint"})
hl.animation({leaf = "fadeOut", enabled = true, speed = 7, bezier = "easeOutQuint"})
hl.animation({leaf = "fade", enabled = true, speed = 7, bezier = "easeOutQuint"})
hl.animation({leaf = "layers", enabled = true, speed = 8, bezier = "fluent"})
hl.animation({leaf = "layersIn", enabled = true, speed = 8, bezier = "smoothIn", style = "slide left"})
hl.animation({leaf = "layersOut", enabled = true, speed = 8, bezier = "smoothOut", style = "slide right"})
hl.animation({leaf = "fadeLayersIn", enabled = true, speed = 7, bezier = "almostLinear"})
hl.animation({leaf = "fadeLayersOut", enabled = true, speed = 7, bezier = "almostLinear"})
hl.animation({leaf = "workspaces",    enabled = true, speed = 7, bezier = "butter", style = "slide 100%"})
hl.animation({leaf = "workspacesIn",  enabled = true, speed = 7, bezier = "butter", style = "slide 100%"})
hl.animation({leaf = "workspacesOut", enabled = true, speed = 7, bezier = "butter", style = "slide 100%"})
hl.animation({leaf = "zoomFactor", enabled = true, speed = 9, bezier = "quick"})


